"""
Meta (Facebook/Instagram) connectors — Ads and Organic.
Supports dynamic level (campaign, adset, ad), conversions parsing, pagination,
daily timeseries (time_increment=1), Instagram Organic connectivity,
comments fetching for Ads/Pages/Instagram, and updated metrics (views replaces
deprecated impressions for IG media created after July 2024).
"""

from typing import List, Dict, Any, Optional
import logging
import httpx
from datetime import datetime, time, timezone

from facebook_business.session import FacebookSession
from facebook_business.api import FacebookAdsApi
from facebook_business.adobjects.adaccount import AdAccount
from facebook_business.adobjects.page import Page

from app.connectors.base import BaseConnector
from app.models.requests import DataRequest
from app.models.responses import CampaignData, CommentData
from app.config import settings

logger = logging.getLogger(__name__)

GRAPH_API_VERSION = "v25.0"
GRAPH_BASE = f"https://graph.facebook.com/{GRAPH_API_VERSION}"


class MetaAdsConnector(BaseConnector):
    platform_name = "meta_ads"

    def get_credentials(self, request: Optional[DataRequest] = None) -> Dict[str, Any]:
        creds = super().get_credentials(request)

        access_token = creds.get("access_token") if creds else None
        if not access_token:
            access_token = settings.meta_access_token

        ad_account_id = request.account_id if request else creds.get("ad_account_id")

        return {
            "access_token": access_token,
            "ad_account_id": ad_account_id
        }

    def fetch_data(self, request: DataRequest) -> List[CampaignData]:
        creds = self.get_credentials(request)
        session = FacebookSession(
            app_id=settings.meta_app_id,
            app_secret=settings.meta_app_secret,
            access_token=creds["access_token"]
        )
        api = FacebookAdsApi(session)
        account = AdAccount(creds["ad_account_id"], api=api)

        # Determine the level from requested dimensions
        level = "campaign"
        if request.dimensions:
            if "ad_name" in request.dimensions or "ad.name" in request.dimensions:
                level = "ad"
            elif "adset_name" in request.dimensions or "adset.name" in request.dimensions:
                level = "adset"

        # Determine fields to request. If conversions or specific pixel action types are requested, request 'actions'
        # Also request actions / action_values for custom/personalized metrics.
        fields = []
        has_actions = False
        has_action_values = False
        STANDARD_META_FIELDS = {
            "impressions", "clicks", "spend", "reach", "conversions", "cpc", "cpm", "ctr", "frequency",
            "results", "cost_per_result", "purchase_roas", "purchase", "lead", "add_to_cart", "initiate_checkout", "roas"
        }
        for m in request.metrics:
            m_mapped = {"roas": "purchase_roas", "__results__": "results"}.get(m, m)
            if m_mapped in ("conversions", "purchase", "lead", "add_to_cart", "initiate_checkout") or m_mapped not in STANDARD_META_FIELDS:
                has_actions = True
                if m_mapped not in STANDARD_META_FIELDS:
                    has_action_values = True
                if "actions" not in fields:
                    fields.append("actions")
                if has_action_values and "action_values" not in fields:
                    fields.append("action_values")
            else:
                if m_mapped not in fields:
                    fields.append(m_mapped)

        # Always include date_start/date_stop to reconstruct date, and name fields for campaign_name mapping
        if "date_start" not in fields:
            fields.append("date_start")
        name_fields = ["campaign_name"]
        if level in ("adset", "ad"):
            name_fields.append("adset_name")
        if level == "ad":
            name_fields.append("ad_name")
        for name_field in name_fields:
            if name_field not in fields:
                fields.append(name_field)

        # Handle breakdown dimensions
        # Map UI-facing dimension names to valid Meta Graph API breakdown values
        VALID_META_BREAKDOWNS = {
            "age", "gender", "country", "comscore_market", "publisher_platform",
            "impression_device", "device_platform", "platform_position",
            "body_asset", "image_asset", "title_asset", "video_asset",
            "description_asset", "region",
        }
        # Translate common UI aliases to valid API breakdown names
        DIMENSION_TO_BREAKDOWN = {
            "platform_device": "impression_device",
            "dma": "comscore_market",
        }

        # ── Meta breakdown compatibility groups ──
        # Meta only allows breakdowns from COMPATIBLE groups in the same request.
        # Asset breakdowns cannot be combined with any other group.
        # Demographic, Geographic, and Delivery can be combined with each other
        # (up to Meta's internal limit, typically ≤3-4 total breakdowns).
        BREAKDOWN_GROUPS = {
            "demographic": {"age", "gender"},
            "geographic": {"country", "region", "comscore_market"},
            "delivery": {"publisher_platform", "platform_position", "impression_device", "device_platform"},
            "asset": {"body_asset", "image_asset", "title_asset", "video_asset", "description_asset"},
        }
        # Asset breakdowns are mutually exclusive with all other groups
        INCOMPATIBLE_PAIRS = {
            frozenset({"asset", "demographic"}),
            frozenset({"asset", "geographic"}),
            frozenset({"asset", "delivery"}),
        }

        breakdowns = []
        if request.dimensions:
            for dim in request.dimensions:
                mapped = DIMENSION_TO_BREAKDOWN.get(dim, dim)
                if mapped in VALID_META_BREAKDOWNS:
                    breakdowns.append(mapped)

        # Validate breakdown group compatibility
        if breakdowns:
            active_groups = set()
            for bd in breakdowns:
                for group_name, group_members in BREAKDOWN_GROUPS.items():
                    if bd in group_members:
                        active_groups.add(group_name)
            # Check for incompatible group combinations
            for pair in INCOMPATIBLE_PAIRS:
                if pair.issubset(active_groups):
                    group_names = sorted(pair)
                    members_by_group = {
                        g: sorted(BREAKDOWN_GROUPS[g] & set(breakdowns))
                        for g in group_names
                    }
                    detail_parts = [f"{g}: {', '.join(members_by_group[g])}" for g in group_names]
                    raise ValueError(
                        f"Meta API does not allow combining these breakdown groups in the same request: "
                        f"{' + '.join(group_names)}. "
                        f"Selected breakdowns by group — {'; '.join(detail_parts)}. "
                        f"Please deselect breakdowns from one of these groups and try again."
                    )

        params = {
            "time_range": {
                "since": request.start_date.strftime("%Y-%m-%d"),
                "until": request.end_date.strftime("%Y-%m-%d")
            },
            "level": level,
            "time_increment": 1  # Get daily timeseries data
        }
        if breakdowns:
            params["breakdowns"] = breakdowns

        # Handle action attribution windows
        if hasattr(request, "action_attribution_windows") and request.action_attribution_windows:
            params["action_attribution_windows"] = request.action_attribution_windows

        # Handle filters translation to Meta's filtering list
        if hasattr(request, "filters") and request.filters:
            if isinstance(request.filters, list):
                params["filtering"] = request.filters
            elif isinstance(request.filters, dict):
                filtering_list = []
                for field, val in request.filters.items():
                    filtering_list.append({
                        "field": field,
                        "operator": "IN" if isinstance(val, list) else "EQUAL",
                        "value": val if isinstance(val, list) else [val]
                    })
                params["filtering"] = filtering_list

        insights = account.get_insights(
            fields=fields,
            params=params
        )

        results = []
        while insights is not None:
            for i in insights:
                campaign_name = i.get("campaign_name") or "Unknown Campaign"
                adset_name = i.get("adset_name")
                ad_name = i.get("ad_name")

                # Append breakdown values to campaign_name to differentiate rows
                for b in breakdowns:
                    b_val = i.get(b)
                    if b_val:
                        campaign_name += f"_{b_val}"

                date_val = i.get("date_start") or request.start_date.strftime("%Y-%m-%d")

                metrics_dict = {}
                for m in request.metrics:
                    m_mapped = {"roas": "purchase_roas", "__results__": "results"}.get(m, m)
                    if m_mapped == "conversions":
                        # Parse standard actions array
                        actions = i.get("actions", [])
                        total_conversions = 0
                        for action in actions:
                            try:
                                total_conversions += int(float(action.get("value", 0)))
                            except Exception:
                                pass
                        metrics_dict["conversions"] = total_conversions
                    elif m_mapped in ("purchase", "lead", "add_to_cart", "initiate_checkout"):
                        actions = i.get("actions", [])
                        action_type_map = {
                            "purchase": ["offsite_conversion.fb_pixel_purchase", "purchase", "app_custom_event.fb_mobile_purchase"],
                            "lead": ["offsite_conversion.fb_pixel_lead", "lead"],
                            "add_to_cart": ["offsite_conversion.fb_pixel_add_to_cart", "add_to_cart"],
                            "initiate_checkout": ["offsite_conversion.fb_pixel_initiate_checkout", "initiate_checkout"]
                        }
                        target_types = action_type_map[m_mapped]
                        val_sum = 0
                        for action in actions:
                            if action.get("action_type") in target_types:
                                try:
                                    val_sum += int(float(action.get("value", 0)))
                                except Exception:
                                    pass
                        metrics_dict[m] = val_sum
                    elif m_mapped not in STANDARD_META_FIELDS:
                        # Personalized/custom metric (e.g. custom conversion or custom pixel event)
                        is_val = m_mapped.endswith("_value")
                        base_m = m_mapped[:-6] if is_val else m_mapped
                        target_array = i.get("action_values" if is_val else "actions", [])
                        val_sum = 0
                        for action in target_array:
